<?php
require_once __DIR__ . '/includes/company_helpers.php';
$kinds=['income'=>'إيراد','expense'=>'مصروف','purchase'=>'مشتريات','loan_advance'=>'سلفة أو قرض صادر','loan_repayment'=>'استرداد سلفة أو سداد قرض'];
if(is_post()){
 require_csrf();$action=input('action');$id=(int)input('id');
 if($action==='void'&&$id>0){$reason=company_input('void_reason',255);$row=db_fetch('SELECT description,amount,voided_at FROM company_transactions WHERE id=?',[$id]);if(!$row){company_flash_error('الحركة المالية غير موجودة.');}elseif($row['voided_at']){company_flash_error('الحركة ملغاة بالفعل.');}elseif(mb_strlen($reason,'UTF-8')<3){company_flash_error('اكتب سببًا مختصرًا لإلغاء الحركة.');}else{db_query('UPDATE company_transactions SET voided_at=NOW(),void_reason=? WHERE id=? AND voided_at IS NULL',[$reason,$id]);company_activity('إلغاء حركة مالية',$row['description'].' — '.company_money($row['amount']).' — '.$reason);flash('success','تم إلغاء الحركة مع الاحتفاظ بسجلها.');}redirect('finance.php');}
 if($action==='save'&&$id>0&&!db_fetch('SELECT id FROM company_transactions WHERE id=? AND voided_at IS NULL',[$id])){company_flash_error('لا يمكن تعديل حركة ملغاة أو غير موجودة.');redirect('finance.php');}
 $kind=company_enum(input('transaction_kind'),array_keys($kinds),'expense');$category=company_input('category',100);$description=company_input('description',255);$amount=company_decimal('amount');$date=company_valid_date(company_input('transaction_date',10));
 $payment=company_enum(input('payment_status'),['pending','paid'],'paid');$method=company_input('payment_method',60);$client=company_optional_id('client_id');$project=company_optional_id('project_id');$employee=company_optional_id('employee_id');
 $supplier=company_input('supplier',190);$reference=company_input('reference_no',120);$rate=company_decimal('tax_rate');$tax=company_decimal('tax_amount');$notes=company_input('notes',5000);
 if(in_array($kind,['loan_advance','loan_repayment'],true)){$rate=0.0;$tax=0.0;}
 $linkedProject=$project?db_fetch('SELECT id,client_id,project_type FROM company_projects WHERE id=?',[$project]):null;
 $clientExists=!$client||db_fetch('SELECT id FROM company_clients WHERE id=?',[$client]);$employeeExists=!$employee||db_fetch('SELECT id FROM company_employees WHERE id=?',[$employee]);
 if($project&&$linkedProject&&!$client&&$linkedProject['client_id'])$client=(int)$linkedProject['client_id'];
 $projectMismatch=$linkedProject&&(($linkedProject['project_type']==='client'&&$linkedProject['client_id']&&$client&&$linkedProject['client_id']!=$client)||($linkedProject['project_type']==='internal'&&$client));
 if($category===''||$description===''||$amount===false||$amount<=0||$date===false||$rate===false||$rate>100||$tax===false||($project&&!$linkedProject)||!$clientExists||!$employeeExists||$projectMismatch){
   company_flash_error('راجع نوع الحركة والتصنيف والوصف والقيمة والتاريخ والضريبة والارتباط بالمشروع والعميل.');
 }else{
   $params=[$kind,$category,$description,$amount,$date,$payment,$method?:null,$client,$project,$employee,$supplier?:null,$reference?:null,$rate,$tax,$notes?:null];
   if($id>0){db_query('UPDATE company_transactions SET transaction_kind=?,category=?,description=?,amount=?,transaction_date=?,payment_status=?,payment_method=?,client_id=?,project_id=?,employee_id=?,supplier=?,reference_no=?,tax_rate=?,tax_amount=?,notes=? WHERE id=?',array_merge($params,[$id]));company_activity('تعديل حركة مالية',$description);flash('success','تم تحديث الحركة المالية.');}
   else{db_query('INSERT INTO company_transactions (transaction_kind,category,description,amount,transaction_date,payment_status,payment_method,client_id,project_id,employee_id,supplier,reference_no,tax_rate,tax_amount,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',array_merge($params,[(int)current_user()['id']]));company_activity('إضافة حركة مالية',$description);flash('success','تم تسجيل الحركة المالية.');}
   redirect('finance.php');
 }
}
$editId=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;$transaction=$editId?db_fetch('SELECT * FROM company_transactions WHERE id=? AND voided_at IS NULL',[$editId]):null;
$clients=db_fetch_all('SELECT id,name FROM company_clients ORDER BY name');$projects=db_fetch_all('SELECT id,name,client_id,project_type FROM company_projects ORDER BY name');$employees=db_fetch_all('SELECT id,full_name FROM company_employees ORDER BY full_name');
$projectFilter=filter_input(INPUT_GET,'project',FILTER_VALIDATE_INT)?:0;$filterKind=company_enum((string)($_GET['kind']??''),array_keys($kinds),'');$from=company_valid_date((string)($_GET['from']??''));$to=company_valid_date((string)($_GET['to']??''));
$conditions=[];$params=[];if($projectFilter){$conditions[]='t.project_id=?';$params[]=$projectFilter;}if($filterKind){$conditions[]='t.transaction_kind=?';$params[]=$filterKind;}if($from){$conditions[]='t.transaction_date>=?';$params[]=$from;}if($to){$conditions[]='t.transaction_date<=?';$params[]=$to;}
$where=$conditions?' WHERE '.implode(' AND ',$conditions):'';
$transactions=db_fetch_all("SELECT t.*,c.name client_name,p.name project_name FROM company_transactions t LEFT JOIN company_clients c ON c.id=t.client_id LEFT JOIN company_projects p ON p.id=t.project_id$where ORDER BY t.transaction_date DESC,t.id DESC LIMIT 500",$params);
$totalWhere=implode(' AND ',array_merge($conditions,['t.voided_at IS NULL']));
$totals=db_fetch("SELECT COALESCE(SUM(CASE WHEN transaction_kind='income' THEN amount ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN transaction_kind='expense' THEN amount ELSE 0 END),0) expenses,COALESCE(SUM(CASE WHEN transaction_kind='purchase' THEN amount ELSE 0 END),0) purchases,COALESCE(SUM(CASE WHEN payment_status='pending' AND transaction_kind='income' THEN amount ELSE 0 END),0) receivable,COALESCE(SUM(CASE WHEN payment_status='pending' AND transaction_kind IN ('expense','purchase') THEN amount ELSE 0 END),0) payable FROM company_transactions t WHERE $totalWhere",$params);
$adminTitle='الحسابات والحركات';$adminSubtitle='الإيرادات والمصروفات والمشتريات والسلف';$adminActive='finance';require __DIR__.'/includes/header.php';
?>
<div class="page-head"><div><h1>الحسابات والحركات المالية</h1><p class="sub">سجّل الإيرادات والمصروفات والمشتريات والسلف، واربط الحركة بالعميل والمشروع والمستفيد عند الحاجة.</p></div></div>
<div class="stats-grid"><div class="stat-card k-green"><div><b><?php echo e(company_money($totals['income'])); ?></b><span>الإيرادات حسب التصفية</span></div></div><div class="stat-card k-red"><div><b><?php echo e(company_money($totals['expenses'])); ?></b><span>المصروفات حسب التصفية</span></div></div><div class="stat-card k-yellow"><div><b><?php echo e(company_money($totals['purchases'])); ?></b><span>المشتريات حسب التصفية</span></div></div><div class="stat-card k-blue"><div><b><?php echo e(company_money($totals['receivable'])); ?></b><span>إيرادات معلقة للتحصيل</span></div></div></div>
<form method="post" action="finance.php<?php echo $transaction?'?edit='.(int)$transaction['id']:''; ?>" data-loading><?php echo csrf_field(); ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?php echo (int)($transaction['id']??0); ?>"><div class="panel"><div class="panel-head"><h2><?php echo $transaction?'تعديل حركة مالية':'تسجيل حركة مالية'; ?></h2></div><div class="panel-body"><div class="form-grid">
<div class="form-group"><label>نوع الحركة</label><select class="form-control" name="transaction_kind"><?php foreach($kinds as $key=>$label): ?><option value="<?php echo e($key); ?>" <?php echo ($transaction['transaction_kind']??'income')===$key?'selected':''; ?>><?php echo e($label); ?></option><?php endforeach; ?></select></div><div class="form-group"><label>التصنيف *</label><input class="form-control" name="category" maxlength="100" required placeholder="تطوير، استضافة، أجهزة، إيجار..." value="<?php echo e($transaction['category']??''); ?>"></div>
<div class="form-group"><label>الوصف *</label><input class="form-control" name="description" maxlength="255" required value="<?php echo e($transaction['description']??''); ?>"></div><div class="form-group"><label>المبلغ قبل الضريبة (ج.م) *</label><input class="form-control ltr" type="number" min="0.01" step="0.01" name="amount" required value="<?php echo e($transaction['amount']??''); ?>"></div>
<div class="form-group"><label>التاريخ *</label><input class="form-control ltr" type="date" name="transaction_date" required value="<?php echo e($transaction['transaction_date']??date('Y-m-d')); ?>"></div><div class="form-group"><label>حالة السداد / التحصيل</label><select class="form-control" name="payment_status"><option value="paid" <?php echo ($transaction['payment_status']??'paid')==='paid'?'selected':''; ?>>تم السداد / التحصيل</option><option value="pending" <?php echo ($transaction['payment_status']??'')==='pending'?'selected':''; ?>>معلق</option></select></div>
<div class="form-group"><label>وسيلة الدفع</label><input class="form-control" name="payment_method" maxlength="60" placeholder="تحويل، نقدي، بطاقة..." value="<?php echo e($transaction['payment_method']??''); ?>"></div><div class="form-group"><label>رقم الفاتورة / المرجع</label><input class="form-control ltr" name="reference_no" maxlength="120" value="<?php echo e($transaction['reference_no']??''); ?>"></div>
<div class="form-group"><label>العميل</label><select class="form-control" name="client_id"><option value="">— غير مرتبط —</option><?php foreach($clients as $c): ?><option value="<?php echo (int)$c['id']; ?>" <?php echo (int)($transaction['client_id']??0)===(int)$c['id']?'selected':''; ?>><?php echo e($c['name']); ?></option><?php endforeach; ?></select></div>
<div class="form-group"><label>المشروع</label><select class="form-control" name="project_id"><option value="">— غير مرتبط —</option><?php foreach($projects as $p): ?><option value="<?php echo (int)$p['id']; ?>" <?php echo (int)($transaction['project_id']??$projectFilter)===(int)$p['id']?'selected':''; ?>><?php echo e($p['name'].($p['project_type']==='internal'?' (داخلي)':'')); ?></option><?php endforeach; ?></select></div>
<div class="form-group"><label>الموظف (عند الحاجة)</label><select class="form-control" name="employee_id"><option value="">— غير مرتبط —</option><?php foreach($employees as $emp): ?><option value="<?php echo (int)$emp['id']; ?>" <?php echo (int)($transaction['employee_id']??0)===(int)$emp['id']?'selected':''; ?>><?php echo e($emp['full_name']); ?></option><?php endforeach; ?></select></div><div class="form-group"><label>المورد / المستفيد</label><input class="form-control" name="supplier" maxlength="190" value="<?php echo e($transaction['supplier']??''); ?>"></div>
<div class="form-group"><label>نسبة الضريبة %</label><input class="form-control ltr" type="number" min="0" max="100" step="0.001" name="tax_rate" value="<?php echo e($transaction['tax_rate']??'0'); ?>"></div><div class="form-group"><label>قيمة الضريبة (ج.م)</label><input class="form-control ltr" type="number" min="0" step="0.01" name="tax_amount" value="<?php echo e($transaction['tax_amount']??'0'); ?>"></div>
<div class="form-group full"><label>ملاحظات</label><textarea class="form-control" name="notes" rows="2" maxlength="5000"><?php echo e($transaction['notes']??''); ?></textarea></div></div><p class="hint">يُسجل المبلغ والضريبة كلٌ على حدة. استخدم قسم الضرائب لتسجيل الالتزام والسداد. الرواتب تُسجل من قسم المرتبات فقط حتى لا تُحسب مرتين. السلف والقروض الصادرة والاستردادات تؤثر على النقدية والذمم ولا تدخل في الإيرادات أو المصروفات أو الأرباح.</p></div><div class="form-actions"><a class="btn btn-outline" href="finance.php">إلغاء</a><div class="right"><button class="btn btn-primary" type="submit">حفظ الحركة</button></div></div></div></form>
